using Microsoft.VisualStudio.TestTools.UnitTesting;
using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _sut = null!;

    [TestInitialize]
    public void Setup()
    {
        _sut = new ShoppingCart();
    }

    // ── AddItem ───────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotal()
    {
        _sut.AddItem("SKU-001", 2, 9.99m);

        Assert.AreEqual(19.98m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_SumsCorrectly()
    {
        _sut.AddItem("SKU-A", 1, 10.00m);
        _sut.AddItem("SKU-B", 3, 5.00m);

        Assert.AreEqual(25.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantities()
    {
        _sut.AddItem("SKU-001", 1, 10.00m);
        _sut.AddItem("SKU-001", 2, 10.00m);

        // Expect 3 × 10.00 = 30.00 (quantities merged)
        Assert.AreEqual(30.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero quantity")]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void AddItem_InvalidQuantity_ThrowsArgumentException(int quantity)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.AddItem("SKU-001", quantity, 5.00m));
    }

    [TestMethod]
    [DataRow(0.0, DisplayName = "Zero price")]
    [DataRow(-5.0, DisplayName = "Negative price")]
    public void AddItem_InvalidPrice_ThrowsArgumentException(double price)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.AddItem("SKU-001", 1, (decimal)price));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    public void AddItem_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.AddItem(sku!, 1, 5.00m));
    }

    // ── RemoveItem ────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _sut.AddItem("SKU-001", 2, 10.00m);
        _sut.RemoveItem("SKU-001");

        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_OneOfMultipleItems_KeepsOtherItems()
    {
        _sut.AddItem("SKU-A", 1, 10.00m);
        _sut.AddItem("SKU-B", 1, 20.00m);

        _sut.RemoveItem("SKU-A");

        Assert.AreEqual(20.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsInvalidOperationException()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _sut.RemoveItem("DOES-NOT-EXIST"));
    }

    // ── CalculateTotal ────────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterAddAndRemove_ReflectsCurrentState()
    {
        _sut.AddItem("SKU-A", 2, 15.00m);
        _sut.AddItem("SKU-B", 1, 7.50m);
        _sut.RemoveItem("SKU-A");

        Assert.AreEqual(7.50m, _sut.CalculateTotal());
    }

    [TestMethod]
    [DataRow(1, 19.99, 19.99, DisplayName = "Single unit")]
    [DataRow(5, 3.50, 17.50, DisplayName = "Multiple units")]
    [DataRow(100, 0.01, 1.00, DisplayName = "Large qty small price")]
    public void CalculateTotal_VariousQuantitiesAndPrices_ComputesCorrectly(
        int qty, double price, double expected)
    {
        _sut.AddItem("SKU-X", qty, (decimal)price);

        Assert.AreEqual((decimal)expected, _sut.CalculateTotal());
    }

    // ── ApplyCoupon ───────────────────────────────────────────

    [TestMethod]
    public void ApplyCoupon_ValidCode_ReducesTotal()
    {
        _sut.AddItem("SKU-001", 1, 100.00m);
        _sut.ApplyCoupon("SAVE10");

        var total = _sut.CalculateTotal();

        Assert.IsTrue(total < 100.00m,
            $"Expected total < 100.00 after coupon, but was {total}");
    }

    [TestMethod]
    public void ApplyCoupon_EmptyCart_DoesNotThrow()
    {
        // Applying a coupon to an empty cart should be safe
        _sut.ApplyCoupon("SAVE10");

        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null coupon code")]
    [DataRow("", DisplayName = "Empty coupon code")]
    public void ApplyCoupon_NullOrEmptyCode_ThrowsArgumentException(string? code)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsInvalidOperationException()
    {
        _sut.AddItem("SKU-001", 1, 50.00m);

        Assert.ThrowsException<InvalidOperationException>(
            () => _sut.ApplyCoupon("BOGUS-CODE"));
    }

    // ── Combined Scenarios ────────────────────────────────────

    [TestMethod]
    public void FullWorkflow_AddItemsApplyCouponRemoveItem_CorrectTotal()
    {
        _sut.AddItem("WIDGET", 2, 25.00m);
        _sut.AddItem("GADGET", 1, 50.00m);
        _sut.ApplyCoupon("SAVE10");
        _sut.RemoveItem("GADGET");

        var total = _sut.CalculateTotal();

        // After removing GADGET, only WIDGET remains (2 × 25 = 50),
        // minus whatever discount SAVE10 applies
        Assert.IsTrue(total <= 50.00m,
            $"Expected total ≤ 50.00 after coupon + removal, but was {total}");
        Assert.IsTrue(total >= 0m, "Total should not be negative");
    }
}

